// Builds Myra's knowledge base (the Suwanee Gamers assistant "brain").
//
// This is the Karpathy "LLM wiki" for Suwanee Gamers: one compact, curated,
// cross-linked Markdown file the voice assistant reads to answer questions about
// the group and site quickly — instead of searching documents on every turn.
//
//   content/assistant-brain.md
//     - A hand-editable curated intro (anything OUTSIDE the AUTO markers).
//     - An auto-generated facts block (BETWEEN the markers) rebuilt from
//       campaigns.json, dungeon-masters.json, and portal-links.json.
//
// The Next.js LiveKit token route reads this file and ships it to the agent in
// the dispatch metadata. Run manually:
//
//   pnpm content:build-assistant-brain
//
// It also runs daily via scripts/content-scheduler.mjs (job id "assistant-brain").
import fs from "fs";
import path from "path";
import { fileURLToPath } from "url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const contentRoot = process.env.SUWANEE_CONTENT_DIR ?? path.join(root, "content");
const brainPath = path.join(contentRoot, "assistant-brain.md");

const AUTO_BEGIN =
  "<!-- AUTO:BEGIN — generated by scripts/build-assistant-brain.mjs; edits inside this block are overwritten -->";
const AUTO_END = "<!-- AUTO:END -->";

const DEFAULT_INTRO = `# Suwanee Gamers — Assistant Knowledge Base

This is the quick-reference brain for Myra, the Suwanee Gamers voice assistant.
Facts below the marker are generated from the site's own content; the prose here is
hand-maintained. Keep answers short, friendly, and grounded only in what is written here.

## What Suwanee Gamers is

Suwanee Gamers is a fantasy-themed portal for a local tabletop RPG (Dungeons & Dragons)
group. The group plays in the shared homebrew world of **Myrdae**. This website is a
lightweight doorway: it surfaces the game calendar, the active campaigns, the Dungeon
Masters and players, and links out to the group's tools.

All canonical lore, character histories, and session records live in **Chronicles** at
kb.suwaneegamers.net — point people there for deep world or story questions.

## How to help visitors

- For "what's on today / next / this week" and "when does <campaign> play", the schedule
  is the source of truth (handled separately). Answer from the live calendar, not from here.
- For "what is this site", "who are the DMs", "what campaigns are there", "where's the lore",
  answer from the facts below.
- If something isn't covered here, say so briefly and point them to the relevant part of the
  site or to Chronicles. Never invent campaigns, people, dates, or links.
`;

function readJson(name) {
  const filePath = path.join(contentRoot, name);
  return JSON.parse(fs.readFileSync(filePath, "utf-8"));
}

function firstSentence(text) {
  const clean = String(text ?? "").trim().replace(/\s+/g, " ");
  if (!clean) return "";
  const match = clean.match(/^.*?[.!?](\s|$)/);
  return (match ? match[0] : clean).trim();
}

function buildAutoBlock() {
  const campaigns = readJson("campaigns.json");
  const dms = readJson("dungeon-masters.json");
  const links = readJson("portal-links.json");

  const campaignNameById = new Map(campaigns.map((c) => [c.id, c.name]));
  const official = campaigns.filter((c) => c.official);
  const pickup = campaigns.filter((c) => !c.official);

  const lines = [];

  lines.push("## Active campaigns");
  lines.push("");
  for (const c of official) {
    const dm = c.dm ? ` — DM ${c.dm}` : "";
    const when = c.schedule ? `, plays ${c.schedule}` : "";
    const blurb = firstSentence(c.description);
    lines.push(`- **${c.name}**${dm}${when}.${blurb ? ` ${blurb}` : ""}`);
  }
  lines.push("");

  if (pickup.length > 0) {
    lines.push("## Pickup / rotating play");
    lines.push("");
    for (const c of pickup) {
      const dm = c.dm ? ` — ${c.dm}` : "";
      const when = c.schedule ? `, ${c.schedule}` : "";
      const blurb = firstSentence(c.description);
      lines.push(`- **${c.name}**${dm}${when}.${blurb ? ` ${blurb}` : ""}`);
    }
    lines.push("");
  }

  lines.push("## Dungeon Masters");
  lines.push("");
  for (const dm of dms) {
    const active = (dm.activeCampaignIds ?? [])
      .map((id) => campaignNameById.get(id) ?? id)
      .filter(Boolean);
    if (active.length === 0) continue;
    const focus = dm.focus ? ` (${firstSentence(dm.focus)})` : "";
    lines.push(`- **${dm.name}**${focus} — runs ${active.join(", ")}.`);
  }
  lines.push("");

  lines.push("## Key links");
  lines.push("");
  for (const link of links) {
    if (!link?.title || !link?.href) continue;
    const desc = link.description ? ` — ${firstSentence(link.description)}` : "";
    lines.push(`- ${link.title}: ${link.href}${desc}`);
  }

  return lines.join("\n").trim();
}

function render(existing, autoBlock) {
  const stamped = `${AUTO_BEGIN}\n<!-- last generated ${new Date().toISOString()} -->\n\n${autoBlock}\n\n${AUTO_END}`;

  if (existing && existing.includes(AUTO_BEGIN) && existing.includes(AUTO_END)) {
    const before = existing.slice(0, existing.indexOf(AUTO_BEGIN)).replace(/\s+$/, "");
    const after = existing.slice(existing.indexOf(AUTO_END) + AUTO_END.length).replace(/^\s+/, "");
    return `${before}\n\n${stamped}${after ? `\n\n${after}` : ""}\n`;
  }

  const intro = (existing && existing.trim() ? existing.trim() : DEFAULT_INTRO).replace(/\s+$/, "");
  return `${intro}\n\n${stamped}\n`;
}

const existing = fs.existsSync(brainPath) ? fs.readFileSync(brainPath, "utf-8") : "";
const output = render(existing, buildAutoBlock());
fs.writeFileSync(brainPath, output, "utf-8");

console.log(
  `[${new Date().toISOString()}] Built assistant brain: ${path.relative(root, brainPath)} (${output.length} chars).`,
);
